    # Frame border
    for r in range(1, out_h - 1):
        for c in range(1, out_w - 1):
            output[r][c] = frame_color

    # Fill 2x2 blocks with scatter colors
    # 4 blocks of 2x2 in reading order
    for i, blk_r in enumerate([2, 2, 2, 2]):
